entries[53407] = { ["name"] = "Richturteil der Gerechtigkeit", ["text"] = "5% von Grundmana 10 Meter Reichweite\nSofort 10 sek. Abklingzeit\nEntfesselt 20 sec lang die Energie eines Siegelzaubers über einem Feind, hindert ihn an der Flucht und schränkt sein Bewegungstempo ein. Bei den einzelnen Siegeln können zusätzliche Effekte des Richturteils nachgelesen werden. Pro Paladin kann immer nur ein Richturteil aktiv sein." }
entries[53408] = { ["name"] = "Richturteil der Weisheit", ["text"] = "5% von Grundmana 10 Meter Reichweite\nSofort 10 sek. Abklingzeit\nEntfesselt die Energien eines Siegelzaubers, um einen Feind 20 sec lang zu richten. Jeder Angriff hat eine Chance, 2% des Grundmanas des Angreifers wiederherzustellen. Bei den einzelnen Siegeln können zusätzliche Effekte des Richturteils nachgelesen werden. Es kann immer nur jeweils ein Richturteil pro Paladin aktiv sein." }
