entries[53717] = { ["name"] = "Leichenexplosion", ["text"] = "20 Meter Reichweite\nWirken in 3 sek.\nBringt einen Leichnam zum Bersten und verursacht bei allen Gegnern innerhalb von 20 Metern 60 Naturschaden (modifiziert durch Angriffskraft). Wird einen Leichnam in der Nähe nutzen, wenn das Ziel kein Leichnam ist. Der Zauber kann nicht auf die Überreste von mechanischen Einheiten oder Elementaren angewendet werden." }
entries[53718] = { ["name"] = "Siegel des Märtyrers", ["text"] = "Unbegrenzte Reichweite\nSofort\nAlle Nahkampfangriffe verursachen zusätzlichen Heiligschaden in Höhe von 48% des normalen Waffenschadens. Dabei verliert der Paladin aber Gesundheit entsprechend 10% des gesamten verursachten Schadens.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Gegner und verursacht sofort Heiligschaden auf Kosten von Gesundheit in Höhe von 33% des verursachten Schadens." }
entries[53719] = { ["name"] = "Siegel des Märtyrers", ["text"] = "Unbegrenzte Reichweite\nSofort\nAlle Nahkampfangriffe verursachen zusätzlichen Heiligschaden in Höhe von 48% des normalen Waffenschadens. Dabei verliert der Paladin aber Gesundheit entsprechend 10% des gesamten verursachten Schadens.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Gegner und verursacht sofort Heiligschaden auf Kosten von Gesundheit in Höhe von 33% des verursachten Schadens." }
entries[53720] = { ["name"] = "Siegel des Märtyrers", ["text"] = "14% von Grundmana\nSofort\nAlle Nahkampfangriffe verursachen (0.48 * Mainhand weapon min damage) bis (0.48 * Mainhand weapon max damage) zusätzlichen Heiligschaden. Dabei verliert der Paladin aber Gesundheit entsprechend 10% des gesamten verursachten Schadens. Hält 30 min lang an.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Gegner und verursacht sofort (0.26 * Mainhand weapon min damage + 0.11 * Attack power + 0.18 * Spell power) bis (0.26 * Mainhand weapon max damage + 0.11 * Attack power + 0.18 * Spell power) Heiligschaden auf Kosten von Gesundheit in Höhe von 33% des verursachten Schadens." }
entries[53721] = { ["name"] = "Tod und Verfall", ["text"] = "30 Meter Reichweite\nSofort\nAlle Ziele im betroffenen Gebiet erleiden 10 sec lang alle 1 Sek. 10 Schattenschaden (modifiziert durch Angriffskraft). Es besteht die Chance, dass sich betroffene Ziele vor Furcht zusammenkauern." }
