entries[53733] = { ["name"] = "Richturteil der Verderbnis", ["text"] = "100 Meter Reichweite\nSofort\nFügt einem Feind (1 + 0.22 * Spell power + 0.14 * Attack power) Heiligschaden zu. Für jeden Stapel von 'Blutverderbnis' auf dem Ziel wird der Schaden um 10% erhöht." }
entries[53736] = { ["name"] = "Siegel der Verderbnis", ["text"] = "14% von Grundmana\nSofort\nErfüllt den Paladin mit heiliger Macht, wodurch Angriffe den Effekt 'Blutverderbnis' auslösen, der im Verlauf von 15 sec [(0.013 * Spell power + 0.025 * Attack power) * 5] zusätzlichen Heiligschaden verursacht. Außerdem verursacht jeder Angriff des Paladins zusätzlich bis zu 33% Waffenschaden als zusätzlichen Heiligschaden abhängig von der Anzahl der Stapel. 'Blutverderbnis' ist bis zu 5-mal stapelbar. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein. Hält 30 min lang an.\n\nDie Entfesselung der Energie dieses Siegels fügt einem Gegner (1 + 0.22 * Spell power + 0.14 * Attack power) Heiligschaden zu, dieser Schaden wird für jeden Stapel von 'Blutverderbnis' auf dem Ziel um 10% erhöht." }
entries[53739] = { ["name"] = "Siegel der Verderbnis", ["text"] = "100 Meter Reichweite\nSofort\nErfüllt den Paladin mit heiliger Macht, wodurch Angriffe den Effekt 'Blutverderbnis' auslösen, der im Verlauf von 15 sec [(0.013 * Spell power + 0.025 * Attack power) * 6] zusätzlichen Heiligschaden verursacht. 'Blutverderbnis' ist bis zu 5-mal stapelbar. Außerdem verursacht jeder Angriff des Paladins zusätzlich bis zu 33% Waffenschaden als zusätzlichen Heiligschaden abhängig von der Anzahl der Stapel. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein. Hält until cancelled lang an.\n\nDie Entfesselung der Energie dieses Siegels fügt einem Gegner (1 + 0.22 * Spell power + 0.14 * Attack power) Heiligschaden zu, dieser Schaden wird für jeden Stapel von 'Blutverderbnis' auf dem Ziel um 10% erhöht." }
